// home.component.ts
import { Component } from '@angular/core';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent {

  categories = [
    { name: 'Bangles', img: 'assets/bangles.jpg' },
    { name: 'Earrings', img: 'assets/earrings.jpg' },
    { name: 'Home Decor', img: 'assets/decor.jpg' },
    { name: 'Wall Hangings', img: 'assets/wall.jpg' },
    { name: 'Gift Sets', img: 'assets/gift.jpg' }
  ];

  products = [
    {
      name: 'Royal Kundan Bangles',
      price: 24.99,
      img: 'assets/bangles1.jpg'
    },
    {
      name: 'Boho Jhumka Earrings',
      price: 18.99,
      img: 'assets/earrings1.jpg'
    },
    {
      name: 'Terracotta Vase',
      price: 34.99,
      img: 'assets/vase.jpg'
    },
    {
      name: 'Macrame Wall Hanging',
      price: 22.99,
      img: 'assets/macrame.jpg'
    }
  ];
}
